  "accounting.mapping.alertRequiredFields": { id: "Transaction key dan akun tujuan wajib diisi.", en: "Transaction key and target account are required.", ms: "Transaction key dan akaun sasaran wajib diisi.", th: "ต้องกรอก transaction key และบัญชีปลายทาง", fil: "Kinakailangan ang transaction key at target account.", vi: "Bắt buộc nhập mã giao dịch (transaction key) và tài khoản đích." },
  "accounting.mapping.confirmDelete": {
    id: 'Hapus mapping "{label}"? Modul ini akan kembali memakai akun default bawaan sistem.',
    en: 'Delete mapping "{label}"? This module will revert to the system\'s built-in default account.',
    ms: 'Padam pemetaan "{label}"? Modul ini akan kembali menggunakan akaun lalai bawaan sistem.',
    th: 'ลบการจับคู่ "{label}" หรือไม่? โมดูลนี้จะกลับไปใช้บัญชีเริ่มต้นของระบบ',
    fil: 'Burahin ang mapping na "{label}"? Babalik ang module na ito sa built-in default account ng sistema.',
    vi: 'Xóa ánh xạ "{label}"? Mô-đun này sẽ quay về sử dụng tài khoản mặc định của hệ thống.',
  },
  "accounting.mapping.explainer": {
    id: "Kasir dan modul lain (Rental, F&B, PPOB, Expense, Asset, Payment) tidak pernah memilih akun COA secara manual — sistem otomatis memilih akun dari tabel ini berdasarkan modul + jenis transaksi. Ubah baris di bawah untuk mengarahkan transaksi ke akun COA lain; hapus baris untuk kembali ke akun default bawaan sistem.",
    en: "Cashiers and other modules (Rental, F&B, PPOB, Expense, Asset, Payment) never pick a COA account manually — the system automatically selects an account from this table based on module + transaction type. Edit a row below to route a transaction to a different COA account; delete a row to revert to the system's built-in default.",
    ms: "Juruwang dan modul lain (Rental, F&B, PPOB, Expense, Asset, Payment) tidak pernah memilih akaun COA secara manual — sistem secara automatik memilih akaun daripada jadual ini berdasarkan modul + jenis transaksi. Ubah baris di bawah untuk mengarahkan transaksi ke akaun COA lain; padam baris untuk kembali ke akaun lalai bawaan sistem.",
    th: "แคชเชียร์และโมดูลอื่นๆ (Rental, F&B, PPOB, Expense, Asset, Payment) ไม่เคยเลือกบัญชี COA ด้วยตนเอง — ระบบจะเลือกบัญชีจากตารางนี้โดยอัตโนมัติตามโมดูล + ประเภทธุรกรรม แก้ไขแถวด้านล่างเพื่อกำหนดให้ธุรกรรมไปยังบัญชี COA อื่น; ลบแถวเพื่อกลับไปใช้บัญชีเริ่มต้นของระบบ",
    fil: "Ang cashier at ibang module (Rental, F&B, PPOB, Expense, Asset, Payment) ay hindi kailanman pumipili ng COA account nang manu-mano — awtomatikong pumipili ang sistema ng account mula sa table na ito batay sa module + uri ng transaksyon. I-edit ang row sa baba para idirekta ang transaksyon sa ibang COA account; burahin ang row para bumalik sa built-in default account ng sistema.",
    vi: "Thu ngân và các mô-đun khác (Rental, F&B, PPOB, Expense, Asset, Payment) không bao giờ tự chọn tài khoản COA thủ công — hệ thống tự động chọn tài khoản từ bảng này dựa trên mô-đun + loại giao dịch. Sửa dòng bên dưới để chuyển hướng giao dịch sang tài khoản COA khác; xóa dòng để quay về tài khoản mặc định của hệ thống.",
  },
  "accounting.mapping.keyWarningTitle": { id: "Tentang kolom \"Transaksi\":", en: "About the \"Transaction\" column:", ms: "Tentang lajur \"Transaksi\":", th: "เกี่ยวกับคอลัมน์ \"ธุรกรรม\":", fil: "Tungkol sa column na \"Transaksyon\":", vi: "Về cột \"Giao dịch\":" },
  "accounting.mapping.keyWarningBody": { id: "kolom ini bukan sekadar nama — ini kunci yang dicari sistem saat memilih akun. Kalau diganti jadi kata yang tidak dikenali sistem, barisnya berhenti dipakai tanpa pesan error apa pun, dan transaksinya kembali memakai akun default bawaan. Kolom \"Label\" aman diubah sesuka Anda; itu murni nama tampilan.", en: "this column is not just a name — it is the key the system looks up when choosing an account. Change it to a word the system does not recognise and the row simply stops being used, with no error message, and the transaction falls back to the built-in default account. The \"Label\" column is safe to change however you like; it is purely a display name.", ms: "lajur ini bukan sekadar nama — ia kunci yang dicari sistem semasa memilih akaun. Jika ditukar kepada perkataan yang tidak dikenali sistem, barisnya berhenti digunakan tanpa sebarang mesej ralat, dan transaksinya kembali kepada akaun lalai. Lajur \"Label\" selamat diubah sesuka hati; ia semata-mata nama paparan.", th: "คอลัมน์นี้ไม่ใช่แค่ชื่อ แต่เป็นคีย์ที่ระบบใช้ค้นหาเมื่อเลือกบัญชี หากเปลี่ยนเป็นคำที่ระบบไม่รู้จัก แถวนั้นจะหยุดถูกใช้งานโดยไม่มีข้อความแจ้งเตือน และธุรกรรมจะกลับไปใช้บัญชีเริ่มต้น ส่วนคอลัมน์ \"Label\" แก้ไขได้ตามต้องการ เพราะเป็นเพียงชื่อที่แสดงผล", fil: "hindi lang pangalan ang column na ito — ito ang key na hinahanap ng sistema kapag pumipili ng account. Kung papalitan ng salitang hindi kilala ng sistema, titigil na lang itong gamitin nang walang error message, at babalik sa default account ang transaksyon. Ligtas baguhin ang \"Label\" column; pangalan lang iyon sa display.", vi: "cột này không chỉ là tên — đó là khóa hệ thống tra cứu khi chọn tài khoản. Đổi thành từ hệ thống không nhận ra thì dòng đó đơn giản ngừng được dùng, không có thông báo lỗi nào, và giao dịch quay về tài khoản mặc định. Cột \"Label\" thì đổi thoải mái; nó thuần túy là tên hiển thị." },
  "accounting.mapping.alertKeyRequired": { id: "Nama transaksi tidak boleh kosong.", en: "The transaction name can't be empty.", ms: "Nama transaksi tidak boleh kosong.", th: "ชื่อธุรกรรมต้องไม่ว่าง", fil: "Hindi pwedeng walang laman ang pangalan ng transaksyon.", vi: "Tên giao dịch không được để trống." },
  "accounting.mapping.placeholderLabelShort": { id: "Nama tampilan (opsional)", en: "Display name (optional)", ms: "Nama paparan (pilihan)", th: "ชื่อที่แสดง (ไม่บังคับ)", fil: "Pangalan sa display (opsyonal)", vi: "Tên hiển thị (tùy chọn)" },
  "accounting.mapping.newMappingButton": { id: "+ Mapping Baru", en: "+ New Mapping", ms: "+ Pemetaan Baharu", th: "+ การจับคู่ใหม่", fil: "+ Bagong Mapping", vi: "+ Ánh xạ mới" },
  "accounting.mapping.placeholderTransactionKey": { id: "Transaction key (mis. ps5, food, pulsa)", en: "Transaction key (e.g. ps5, food, pulsa)", ms: "Transaction key (cth. ps5, food, pulsa)", th: "Transaction key (เช่น ps5, food, pulsa)", fil: "Transaction key (hal. ps5, food, pulsa)", vi: "Mã giao dịch (vd. ps5, food, pulsa)" },
  "accounting.mapping.chooseTargetAccount": { id: "Pilih akun tujuan...", en: "Select the target account...", ms: "Pilih akaun sasaran...", th: "เลือกบัญชีปลายทาง...", fil: "Piliin ang target account...", vi: "Chọn tài khoản đích..." },
