  "accounting.mapping.saveMappingButton": { id: "Simpan Mapping", en: "Save Mapping", ms: "Simpan Pemetaan", th: "บันทึกการจับคู่", fil: "I-save ang Mapping", vi: "Lưu ánh xạ" },
