  // --- TrialBalanceTab ---
  "accounting.trialBalance.abnormalTitle": { id: "{n} akun bersaldo berlawanan arah", en: "{n} account(s) have an abnormal balance", ms: "{n} akaun berbaki bertentangan arah", th: "{n} บัญชีมียอดคงเหลือผิดด้าน", fil: "{n} account ang may abnormal na balanse", vi: "{n} tài khoản có số dư ngược dấu" },
  "accounting.trialBalance.abnormalBody": { id: "Aset tidak bisa bernilai kurang dari nol, dan liabilitas tidak bisa menjadi piutang. Saldo seperti ini berarti ada transaksi yang belum tercatat — paling sering: setoran/top-up yang sudah dilakukan di dunia nyata tapi belum dimasukkan ke sistem. Pembukuan tetap seimbang, jadi \"Balance ✓\" di bawah tidak akan menangkapnya.", en: "An asset can't be worth less than zero, and a liability can't turn into a receivable. A balance like this means a transaction hasn't been recorded — most often a top-up or deposit that really happened but was never entered. The books still balance, so the \"Balance ✓\" below will not catch it.", ms: "Aset tidak boleh kurang daripada sifar, dan liabiliti tidak boleh menjadi penghutang. Baki begini bermakna ada transaksi belum direkodkan — selalunya tambah nilai atau deposit yang benar-benar berlaku tetapi tidak pernah dimasukkan. Buku tetap seimbang, jadi \"Balance ✓\" di bawah tidak akan menangkapnya.", th: "สินทรัพย์ต้องไม่ต่ำกว่าศูนย์ และหนี้สินไม่อาจกลายเป็นลูกหนี้ ยอดเช่นนี้หมายความว่ามีธุรกรรมที่ยังไม่ได้บันทึก — ส่วนใหญ่คือการเติมเงินหรือฝากเงินที่เกิดขึ้นจริงแต่ไม่เคยถูกบันทึก บัญชียังคงสมดุล ดังนั้น \"Balance ✓\" ด้านล่างจะไม่จับข้อผิดพลาดนี้", fil: "Hindi pwedeng mas mababa sa zero ang asset, at hindi pwedeng maging receivable ang liability. Ang ganitong balanse ay nangangahulugang may transaksyong hindi naitala — kadalasan ay top-up o deposit na totoong nangyari pero hindi naipasok. Balanse pa rin ang libro, kaya hindi ito mahuhuli ng \"Balance ✓\" sa ibaba.", vi: "Tài sản không thể nhỏ hơn 0, và nợ phải trả không thể thành khoản phải thu. Số dư như vậy nghĩa là có giao dịch chưa được ghi nhận — thường là khoản nạp hoặc gửi tiền đã xảy ra thật nhưng chưa nhập. Sổ sách vẫn cân, nên \"Balance ✓\" bên dưới sẽ không phát hiện được." },
  "accounting.trialBalance.abnormalTooltip": { id: "Saldo berlawanan arah — lihat peringatan di atas tabel.", en: "Abnormal balance — see the warning above the table.", ms: "Baki bertentangan arah — lihat amaran di atas jadual.", th: "ยอดคงเหลือผิดด้าน — ดูคำเตือนเหนือตาราง", fil: "Abnormal na balanse — tingnan ang babala sa itaas ng talahanayan.", vi: "Số dư ngược dấu — xem cảnh báo phía trên bảng." },
  "accounting.trialBalance.drillDownHint": { id: "Klik baris akun mana pun untuk melihat jurnal yang menyusun angkanya pada periode ini (audit trail). Akun induk yang dicetak tebal hanya menjumlahkan turunannya, jadi tidak bisa diklik.", en: "Click any account row to see the journal entries behind its figures for this period (audit trail). Bold parent accounts only total up their children, so they aren't clickable.", ms: "Klik mana-mana baris akaun untuk melihat jurnal yang membentuk angkanya bagi tempoh ini (audit trail). Akaun induk bercetak tebal hanya menjumlahkan turunannya, jadi tidak boleh diklik.", th: "คลิกแถวบัญชีใดก็ได้เพื่อดูสมุดรายวันที่ประกอบเป็นตัวเลขในงวดนี้ (audit trail) บัญชีหลักตัวหนาเป็นเพียงผลรวมของบัญชีย่อย จึงคลิกไม่ได้", fil: "I-click ang alinmang row ng account para makita ang journal entries sa likod ng numero nito para sa panahong ito (audit trail). Ang naka-bold na parent account ay kabuuan lang ng mga anak nito, kaya hindi ito makli-click.", vi: "Nhấp vào bất kỳ dòng tài khoản nào để xem các bút toán tạo nên con số trong kỳ này (dấu vết kiểm toán). Tài khoản cha in đậm chỉ cộng dồn tài khoản con nên không nhấp được." },
  "accounting.trialBalance.drillDownRowTitle": { id: "Klik untuk melihat isinya", en: "Click to see what's inside", ms: "Klik untuk melihat isinya", th: "คลิกเพื่อดูรายละเอียด", fil: "I-click para makita ang laman", vi: "Nhấp để xem chi tiết" },
  "accounting.trialBalance.drillDownTotal": { id: "Saldo (sesuai Neraca Saldo)", en: "Balance (as in the Trial Balance)", ms: "Baki (seperti Imbangan Duga)", th: "ยอดคงเหลือ (ตามงบทดลอง)", fil: "Balanse (gaya sa Trial Balance)", vi: "Số dư (theo Bảng cân đối thử)" },
  "accounting.trialBalance.table.turnoverNote": { id: "perputaran", en: "turnover", ms: "pusing ganti", th: "การหมุนเวียน", fil: "turnover", vi: "phát sinh" },
  "accounting.trialBalance.table.balanceNote": { id: "sisa sebenarnya", en: "what's actually left", ms: "baki sebenar", th: "ยอดคงเหลือจริง", fil: "tunay na natitira", vi: "số còn lại thực tế" },
  "accounting.ledger.turnoverSummary": { id: "Selama periode ini akun bertambah {naik} dan berkurang {turun}, sehingga tersisa {sisa}. Angka besar di kolom Debit/Kredit Neraca Saldo adalah pergerakan itu — bukan sisanya.", en: "Over this period the account increased by {naik} and decreased by {turun}, leaving {sisa}. The large figures in the Trial Balance's Debit/Credit columns are that movement — not what remains.", ms: "Sepanjang tempoh ini akaun bertambah {naik} dan berkurang {turun}, menjadikan baki {sisa}. Angka besar di lajur Debit/Kredit Imbangan Duga ialah pergerakan itu — bukan bakinya.", th: "ในงวดนี้บัญชีเพิ่มขึ้น {naik} และลดลง {turun} เหลือ {sisa} ตัวเลขขนาดใหญ่ในคอลัมน์เดบิต/เครดิตของงบทดลองคือความเคลื่อนไหวนั้น ไม่ใช่ยอดคงเหลือ", fil: "Sa panahong ito, tumaas ang account ng {naik} at bumaba ng {turun}, kaya {sisa} ang natira. Ang malalaking numero sa Debit/Credit ng Trial Balance ay ang galaw na iyon — hindi ang natitira.", vi: "Trong kỳ này tài khoản tăng {naik} và giảm {turun}, còn lại {sisa}. Các con số lớn ở cột Nợ/Có của Bảng cân đối thử là biến động đó — không phải số còn lại." },
  "accounting.trialBalance.showZeroLabel": { id: "Tampilkan akun bersaldo nol (terinci lengkap)", en: "Show zero-balance accounts (fully detailed)", ms: "Papar akaun berbaki sifar (terperinci penuh)", th: "แสดงบัญชีที่มียอดคงเหลือเป็นศูนย์ (รายละเอียดครบถ้วน)", fil: "Ipakita ang mga account na zero balance (buong detalye)", vi: "Hiện tài khoản có số dư bằng không (chi tiết đầy đủ)" },
