  "accounting.cf.cashInDetail": { id: "Rincian Kas Masuk", en: "Cash In Breakdown", ms: "Perincian Tunai Masuk", th: "รายละเอียดเงินสดรับ", fil: "Detalye ng Cash In", vi: "Chi tiết tiền vào" },
  "accounting.cf.cashOutDetail": { id: "Rincian Kas Keluar", en: "Cash Out Breakdown", ms: "Perincian Tunai Keluar", th: "รายละเอียดเงินสดจ่าย", fil: "Detalye ng Cash Out", vi: "Chi tiết tiền ra" },
  "accounting.cf.noData": { id: "Tidak ada data.", en: "No data.", ms: "Tiada data.", th: "ไม่มีข้อมูล", fil: "Walang data.", vi: "Không có dữ liệu." },
  "accounting.pl.cogsMissingTitle": { id: "HPP belum terhitung — Laba Kotor di atas belum mencerminkan modal barang", en: "COGS not recorded — the Gross Profit above does not yet reflect the cost of goods", ms: "HPP belum dikira — Untung Kasar di atas belum mencerminkan kos barang", th: "ยังไม่ได้บันทึกต้นทุนขาย — กำไรขั้นต้นด้านบนยังไม่สะท้อนต้นทุนสินค้า", fil: "Hindi pa naitatala ang COGS — hindi pa sinasalamin ng Gross Profit sa itaas ang puhunan sa paninda", vi: "Chưa ghi nhận giá vốn — Lợi nhuận gộp ở trên chưa phản ánh giá vốn hàng bán" },
  "accounting.pl.cogsMissingBody": { id: "Ada penjualan barang senilai {revenue} pada periode ini, tapi HPP-nya nol karena {n} produk aktif masih kosong Harga Modal-nya. Selama itu kosong, setiap penjualannya dihitung untung penuh.", en: "There were {revenue} of goods sales this period, but COGS is zero because {n} active products still have no Cost Price. While that is empty, every sale is counted as pure profit.", ms: "Terdapat jualan barang bernilai {revenue} dalam tempoh ini, tetapi HPP sifar kerana {n} produk aktif masih tiada Harga Kos. Selagi kosong, setiap jualan dikira untung penuh.", th: "มียอดขายสินค้า {revenue} ในงวดนี้ แต่ต้นทุนขายเป็นศูนย์เพราะสินค้าที่ใช้งานอยู่ {n} รายการยังไม่มีต้นทุน ตราบใดที่ยังว่าง ทุกการขายจะถูกนับเป็นกำไรเต็มจำนวน", fil: "May benta ng paninda na {revenue} ngayong panahon, pero zero ang COGS dahil {n} aktibong produkto ang wala pa ring Cost Price. Habang walang laman iyon, bawat benta ay binibilang na purong tubo.", vi: "Có {revenue} doanh thu bán hàng trong kỳ này, nhưng giá vốn bằng 0 vì {n} sản phẩm đang hoạt động vẫn chưa có Giá vốn. Khi còn trống, mọi giao dịch đều được tính là lãi trọn vẹn." },
  "accounting.pl.cogsMissingFix": { id: "Isi Harga Modal di Inventory Control → Produk, atau catat pembelian lewat Belanja Supplier supaya terisi otomatis. HPP hanya terhitung untuk penjualan SETELAH Harga Modal terisi — transaksi lama tidak berubah sendiri.", en: "Fill in Cost Price under Inventory Control → Products, or record a purchase via Supplier Purchase to fill it automatically. COGS is only computed for sales made AFTER the Cost Price is set — past transactions do not change on their own.", ms: "Isi Harga Kos di Inventory Control → Produk, atau rekod belian melalui Belian Pembekal supaya terisi automatik. HPP hanya dikira untuk jualan SELEPAS Harga Kos diisi — transaksi lama tidak berubah sendiri.", th: "กรอกต้นทุนที่ Inventory Control → สินค้า หรือบันทึกการซื้อผ่านการซื้อจากซัพพลายเออร์เพื่อให้กรอกอัตโนมัติ ต้นทุนขายจะคำนวณเฉพาะการขายหลังจากกำหนดต้นทุนแล้ว — รายการเดิมจะไม่เปลี่ยนเอง", fil: "Ilagay ang Cost Price sa Inventory Control → Products, o mag-record ng bili sa Supplier Purchase para awtomatikong mapunan. Kinukuwenta lang ang COGS para sa mga bentang PAGKATAPOS maitakda ang Cost Price — hindi kusang nagbabago ang lumang transaksyon.", vi: "Điền Giá vốn ở Inventory Control → Sản phẩm, hoặc ghi nhận mua hàng qua Mua hàng NCC để tự động điền. Giá vốn chỉ được tính cho các giao dịch SAU khi đã đặt Giá vốn — giao dịch cũ không tự thay đổi." },
  "accounting.cf.sourceNote": { id: "Dihitung dari mutasi akun {accounts} di jurnal — totalnya selalu cocok dengan Neraca Saldo untuk periode yang sama.", en: "Computed from journal movements on {accounts} — always reconciles with the Trial Balance for the same period.", ms: "Dikira daripada pergerakan akaun {accounts} dalam jurnal — sentiasa sepadan dengan Imbangan Duga bagi tempoh yang sama.", th: "คำนวณจากความเคลื่อนไหวของบัญชี {accounts} ในสมุดรายวัน — ตรงกับงบทดลองของงวดเดียวกันเสมอ", fil: "Kinuwenta mula sa galaw ng {accounts} sa journal — laging tugma sa Trial Balance ng parehong panahon.", vi: "Tính từ biến động tài khoản {accounts} trong sổ nhật ký — luôn khớp với Bảng cân đối thử của cùng kỳ." },
  "accounting.cf.dailyCashFlow": { id: "Arus Kas Harian", en: "Daily Cash Flow", ms: "Aliran Tunai Harian", th: "กระแสเงินสดรายวัน", fil: "Araw-araw na Cash Flow", vi: "Lưu chuyển tiền hàng ngày" },
