  "accounting.migration.categoryPendapatanLain": { id: "Pendapatan Lain-lain", en: "Other Income", ms: "Pendapatan Lain", th: "รายได้อื่นๆ", fil: "Iba pang Kita", vi: "Thu nhập khác" },
  "accounting.migration.categoryPengeluaran": { id: "Pengeluaran", en: "Expenses", ms: "Perbelanjaan", th: "รายจ่าย", fil: "Gastos", vi: "Chi phí" },
  "accounting.migration.descPenjualan": { id: "Total penjualan lama (per hari/per transaksi) beserta metode pembayaran.", en: "Old total sales (per day/per transaction) along with the payment method.", ms: "Jumlah jualan lama (setiap hari/setiap transaksi) berserta kaedah pembayaran.", th: "ยอดขายรวมเก่า (รายวัน/รายธุรกรรม) พร้อมวิธีการชำระเงิน", fil: "Lumang kabuuang benta (kada araw/kada transaksyon) kasama ang paraan ng pagbabayad.", vi: "Tổng doanh số cũ (theo ngày/theo giao dịch) kèm phương thức thanh toán." },
  "accounting.migration.descPembelian": { id: "Pembelian stok/bahan baku atau operasional lama, tunai atau hutang.", en: "Old stock/ingredient or operational purchases, cash or on credit.", ms: "Belian stok/bahan mentah atau operasi lama, tunai atau hutang.", th: "การซื้อสต็อก/วัตถุดิบ หรือค่าใช้จ่ายดำเนินงานเก่า ทั้งเงินสดหรือเงินเชื่อ", fil: "Lumang bili ng stock/sangkap o operational, cash o utang.", vi: "Mua hàng tồn kho/nguyên liệu hoặc chi phí vận hành cũ, tiền mặt hoặc công nợ." },
  "accounting.migration.descPendapatanLain": { id: "Komisi, sewa aset, penjualan barang bekas, dan pendapatan non-inti lain dari masa lalu.", en: "Commission, asset rental, sale of used goods, and other non-core income from the past.", ms: "Komisen, sewa aset, jualan barang terpakai, dan pendapatan bukan teras lain dari masa lalu.", th: "ค่าคอมมิชชั่น ค่าเช่าสินทรัพย์ การขายของใช้แล้ว และรายได้นอกเหนือธุรกิจหลักอื่นๆ ในอดีต", fil: "Komisyon, upa sa asset, benta ng gamit na na, at iba pang non-core na kita noong nakaraan.", vi: "Hoa hồng, cho thuê tài sản, bán đồ cũ, và thu nhập ngoài hoạt động chính khác trong quá khứ." },
  "accounting.migration.descPengeluaran": { id: "Beban operasional lama (gaji, sewa, listrik, internet, dll), tunai atau hutang.", en: "Old operating expenses (salaries, rent, electricity, internet, etc.), cash or on credit.", ms: "Perbelanjaan operasi lama (gaji, sewa, elektrik, internet, dll), tunai atau hutang.", th: "ค่าใช้จ่ายดำเนินงานเก่า (เงินเดือน ค่าเช่า ค่าไฟ อินเทอร์เน็ต ฯลฯ) ทั้งเงินสดหรือเงินเชื่อ", fil: "Lumang operating expense (sweldo, upa, kuryente, internet, atbp.), cash o utang.", vi: "Chi phí vận hành cũ (lương, thuê mặt bằng, điện, internet, v.v.), tiền mặt hoặc công nợ." },

  // --- OpeningBalanceCard ---
  "accounting.openingBalance.heading": { id: "Saldo Awal (Opening Balance)", en: "Opening Balance", ms: "Baki Pembukaan (Opening Balance)", th: "ยอดยกมา (Opening Balance)", fil: "Opening Balance", vi: "Số dư đầu kỳ (Opening Balance)" },
  "accounting.openingBalance.description": {
    id: "Satu jurnal berisi saldo tiap akun (Kas, Bank, Piutang, Hutang, Aset, Modal, dst.) per tanggal cutover — cara standar migrasi sistem akuntansi, tanpa perlu memindahkan tiap transaksi lama satu-satu. Total debit harus sama dengan total kredit.",
    en: "A single journal entry holding the balance of every account (Cash, Bank, Receivables, Payables, Assets, Equity, etc.) as of the cutover date — the standard way to migrate an accounting system, without moving every old transaction one by one. Total debit must equal total credit.",
    ms: "Satu jurnal mengandungi baki setiap akaun (Tunai, Bank, Piutang, Hutang, Aset, Modal, dll.) setakat tarikh cutover — cara standard migrasi sistem perakaunan, tanpa perlu memindahkan setiap transaksi lama satu-satu. Jumlah debit mesti sama dengan jumlah kredit.",
    th: "สมุดรายวันเดียวที่รวมยอดคงเหลือของทุกบัญชี (เงินสด ธนาคาร ลูกหนี้ เจ้าหนี้ สินทรัพย์ ทุน ฯลฯ) ณ วันที่เริ่มใช้งาน — วิธีมาตรฐานในการย้ายระบบบัญชี โดยไม่ต้องย้ายทุกธุรกรรมเก่าทีละรายการ ยอดเดบิตรวมต้องเท่ากับยอดเครดิตรวม",
    fil: "Iisang journal entry na naglalaman ng balanse ng bawat account (Cash, Bank, Receivable, Payable, Asset, Equity, atbp.) bilang ng cutover date — ang standard na paraan ng pag-migrate ng accounting system, nang hindi kailangang ilipat ang bawat lumang transaksyon isa-isa. Dapat magkapareho ang kabuuang debit at kabuuang credit.",
    vi: "Một bút toán duy nhất chứa số dư của mọi tài khoản (Tiền mặt, Ngân hàng, Phải thu, Phải trả, Tài sản, Vốn, v.v.) tính đến ngày chuyển đổi — cách chuẩn để di chuyển hệ thống kế toán mà không cần chuyển từng giao dịch cũ một. Tổng nợ phải bằng tổng có.",
  },
