  "accounting.openingBalance.postButton": { id: "Posting Saldo Awal", en: "Post Opening Balance", ms: "Posting Baki Pembukaan", th: "บันทึกยอดยกมา", fil: "I-post ang Opening Balance", vi: "Ghi sổ số dư đầu kỳ" },
  "accounting.openingBalance.validationMsg": { id: "Total debit harus sama dengan total kredit, dan lebih dari 0.", en: "Total debit must equal total credit, and be greater than 0.", ms: "Jumlah debit mesti sama dengan jumlah kredit, dan lebih daripada 0.", th: "ยอดเดบิตรวมต้องเท่ากับยอดเครดิตรวม และมากกว่า 0", fil: "Dapat magkapareho ang kabuuang debit at credit, at higit sa 0.", vi: "Tổng nợ phải bằng tổng có, và lớn hơn 0." },
